CREATE TABLE IF NOT EXISTS african_asset_intelligence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid NOT NULL, state text NOT NULL DEFAULT 'insufficient_data', overall_score numeric(6,2) NOT NULL DEFAULT 0, evidence_score numeric(6,2) NOT NULL DEFAULT 0, network_score numeric(6,2) NOT NULL DEFAULT 0, economic_score numeric(6,2) NOT NULL DEFAULT 0, verification_score numeric(6,2) NOT NULL DEFAULT 0, capital_readiness_score numeric(6,2) NOT NULL DEFAULT 0, strengths jsonb NOT NULL DEFAULT '[]'::jsonb, risks jsonb NOT NULL DEFAULT '[]'::jsonb, opportunities jsonb NOT NULL DEFAULT '[]'::jsonb, missing_evidence jsonb NOT NULL DEFAULT '[]'::jsonb, next_actions jsonb NOT NULL DEFAULT '[]'::jsonb, model_version text NOT NULL DEFAULT 'OV-15-RULES-V1', created_at timestamptz NOT NULL DEFAULT now());